// supabase/dashboard/wa-template/index.ts
// Self-contained copy of supabase/functions/wa-template for pasting into the Supabase dashboard editor.
// Function name in Supabase must be exactly: wa-template   ·   Turn OFF "Verify JWT" for this function.
// @ts-nocheck  (bundled JavaScript — the typed source lives in supabase/functions)

// supabase/functions/_shared/supabase.ts
import { createClient } from "npm:@supabase/supabase-js@2";
function secretKey() {
  const raw = Deno.env.get("SUPABASE_SECRET_KEYS");
  if (raw) {
    try {
      const keys = JSON.parse(raw);
      const key = keys.default ?? Object.values(keys)[0];
      if (key) return key;
    } catch {
    }
  }
  const legacy = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!legacy) throw new Error("No Supabase secret key in environment");
  return legacy;
}
function adminClient() {
  return createClient(Deno.env.get("SUPABASE_URL"), secretKey(), {
    auth: { persistSession: false, autoRefreshToken: false }
  });
}
async function getUser(req, admin) {
  const token = req.headers.get("Authorization")?.replace(/^Bearer\s+/i, "");
  if (!token) return null;
  const { data, error } = await admin.auth.getUser(token);
  if (error || !data.user) return null;
  return data.user;
}
async function isMember(admin, userId, businessId) {
  const [{ data: member }, { data: profile }] = await Promise.all([
    admin.from("business_members").select("user_id").eq("business_id", businessId).eq("user_id", userId).maybeSingle(),
    admin.from("profiles").select("is_platform_admin").eq("id", userId).maybeSingle()
  ]);
  return !!member || !!profile?.is_platform_admin;
}

// supabase/functions/_shared/http.ts
var corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-api-key, x-cron-secret",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS"
};
function json(body, status = 200, extra = {}) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json", ...extra }
  });
}
function preflight(req) {
  return req.method === "OPTIONS" ? new Response("ok", { headers: corsHeaders }) : null;
}

// supabase/functions/_shared/font.ts
var FIRA_SANS_BOLD_LATIN = "";

// supabase/functions/_shared/reviewImage.ts
var D = Deno;
D.core ??= {};
D.core.encode ??= (s) => new TextEncoder().encode(s);
var W = 800;
var H = 600;
var LATIN = /^[\x20-\x7E -ÿ‘-”]+$/;
var fontBytes = null;
function font() {
  if (!fontBytes) fontBytes = Uint8Array.from(atob(FIRA_SANS_BOLD_LATIN), (c) => c.charCodeAt(0));
  return fontBytes;
}
function labelText(firstName) {
  const name = (firstName || "").trim().split(/\s+/)[0] ?? "";
  return name && name.length <= 22 && LATIN.test(name) ? `${name}!` : "Thank you!";
}
async function renderReviewImage(photoUrl, firstName) {
  const { Image } = await import("npm:imagescript@1.3.0");
  let canvas = new Image(W, H).fill(Image.rgbaToColor(23, 103, 46, 255));
  if (photoUrl && /^https?:\/\//i.test(photoUrl)) {
    try {
      const res = await fetch(photoUrl);
      if (res.ok) {
        const decoded = await Image.decode(new Uint8Array(await res.arrayBuffer()));
        if (decoded instanceof Image) {
          const scale = Math.max(W / decoded.width, H / decoded.height);
          const resized = decoded.resize(Math.ceil(decoded.width * scale), Math.ceil(decoded.height * scale));
          canvas = resized.crop(Math.floor((resized.width - W) / 2), Math.floor((resized.height - H) / 2), W, H);
        }
      }
    } catch {
    }
  }
  const text = labelText(firstName);
  let size = 72;
  let rendered = await Image.renderText(font(), size, text, Image.rgbaToColor(17, 17, 17, 255));
  while (rendered.width > W * 0.86 && size > 30) {
    size -= 6;
    rendered = await Image.renderText(font(), size, text, Image.rgbaToColor(17, 17, 17, 255));
  }
  const padX = Math.round(size * 0.4);
  const padY = Math.round(size * 0.12);
  const label = new Image(rendered.width + padX * 2, rendered.height + padY * 2).fill(4294967295).roundCorners(Math.round(size * 0.22));
  label.composite(rendered, padX, padY);
  canvas.composite(label, Math.round((W - label.width) / 2), H - label.height - 32);
  return await canvas.encodeJPEG(85);
}

// supabase/functions/_shared/waTemplates.ts
var env = (k) => Deno.env.get(k) ?? "";
var EXAMPLES = { first_name: "Priya", review_link: "https://g.page/r/example/review" };
async function metaConfig(admin, businessId) {
  const { data: row } = await admin.from("business_channels").select("*").eq("business_id", businessId).maybeSingle();
  return {
    wabaId: row?.whatsapp_waba_id || env("WHATSAPP_WABA_ID"),
    appId: env("WHATSAPP_APP_ID"),
    token: row?.whatsapp_access_token || env("WHATSAPP_ACCESS_TOKEN"),
    version: env("WHATSAPP_API_VERSION") || "v23.0",
    lang: row?.whatsapp_template_lang || env("WHATSAPP_TEMPLATE_LANG") || "en"
  };
}
function buildTemplateBody(source, vars) {
  let text = source.replace(/\{business_name\}/g, vars.businessName).replace(/\{owner_name\}/g, vars.ownerName || vars.businessName).replace(/\r\n/g, "\n").replace(/\n{3,}/g, "\n\n").trim();
  const params = [];
  text = text.replace(/\{(first_name|review_link)\}/g, (_m, key) => {
    params.push(key);
    return `{{${params.length}}}`;
  });
  if (/^\{\{\d+\}\}/.test(text)) text = `Hi ${text}`;
  if (/\{\{\d+\}\}[\s.!?,]*$/.test(text)) text = `${text} Thank you!`;
  text = text.replace(/(\{\{\d+\}\})\s*(\{\{\d+\}\})/g, "$1 - $2");
  return { body: text, params, example: params.map((p) => EXAMPLES[p]) };
}
function templateName(businessId, kind) {
  return `lo_${businessId.replace(/-/g, "").slice(0, 10)}_${kind}_${Date.now().toString(36)}`;
}
function mapStatus(meta) {
  switch ((meta ?? "").toUpperCase()) {
    case "APPROVED":
      return "approved";
    case "REJECTED":
      return "rejected";
    case "PAUSED":
      return "paused";
    case "DISABLED":
      return "disabled";
    default:
      return "pending";
  }
}
async function graph(cfg, path, init = {}) {
  const res = await fetch(`https://graph.facebook.com/${cfg.version}/${path}`, {
    ...init,
    headers: { Authorization: `Bearer ${cfg.token}`, ...init.headers ?? {} }
  });
  const body = await res.json().catch(() => ({}));
  if (!res.ok) {
    const e = body?.error;
    throw new Error(e?.error_user_msg || e?.message || `Meta HTTP ${res.status}`);
  }
  return body;
}
async function uploadSampleImage(cfg, jpeg) {
  if (!cfg.appId) throw new Error("WHATSAPP_APP_ID is not set (needed for the photo template)");
  const session = await graph(
    cfg,
    `${cfg.appId}/uploads?file_name=sample.jpg&file_length=${jpeg.byteLength}&file_type=image/jpeg`,
    { method: "POST" }
  );
  const res = await fetch(`https://graph.facebook.com/${cfg.version}/${session.id}`, {
    method: "POST",
    headers: { Authorization: `OAuth ${cfg.token}`, file_offset: "0" },
    body: new Blob([jpeg])
  });
  const body = await res.json().catch(() => ({}));
  if (!res.ok || !body.h) throw new Error(body?.error?.message ?? "Sample image upload failed");
  return body.h;
}
async function createTemplate(cfg, name, body, example, headerHandle) {
  const components = [];
  if (headerHandle) components.push({ type: "HEADER", format: "IMAGE", example: { header_handle: [headerHandle] } });
  components.push({ type: "BODY", text: body, ...example.length ? { example: { body_text: [example] } } : {} });
  const res = await graph(cfg, `${cfg.wabaId}/message_templates`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name, language: cfg.lang, category: "MARKETING", components })
  });
  return { id: String(res.id), status: mapStatus(res.status) };
}
async function fetchTemplateStatus(cfg, id) {
  const res = await graph(cfg, `${id}?fields=status,rejected_reason`);
  const reason = res.rejected_reason && res.rejected_reason !== "NONE" ? String(res.rejected_reason) : null;
  return { status: mapStatus(res.status), reason };
}

// supabase/functions/wa-template/index.ts
var COLS = "id, kind, name, body, status, reason, created_at, updated_at";
Deno.serve(async (req) => {
  const pre = preflight(req);
  if (pre) return pre;
  if (req.method !== "POST") return json({ error: "Use POST" }, 405);
  const admin = adminClient();
  const user = await getUser(req, admin);
  if (!user) return json({ error: "Sign in required" }, 401);
  const { businessId, action = "refresh", kinds } = await req.json().catch(() => ({}));
  if (!businessId) return json({ error: "businessId is required" }, 400);
  if (!await isMember(admin, user.id, businessId)) return json({ error: "Not allowed" }, 403);
  const cfg = await metaConfig(admin, businessId);
  if (!cfg.wabaId || !cfg.token) return json({ error: "WhatsApp is not connected yet (WHATSAPP_WABA_ID / WHATSAPP_ACCESS_TOKEN missing)" }, 400);
  const warnings = [];
  if (action === "submit") {
    const { data: b } = await admin.from("businesses").select("name, messaging").eq("id", businessId).single();
    if (!b) return json({ error: "Business not found" }, 404);
    const m = b.messaging ?? {};
    const vars = { businessName: m.businessName || b.name, ownerName: m.ownerFirstName || "" };
    const want = new Set(kinds?.length ? kinds : ["initial", "followup"]);
    const jobs = [];
    if (want.has("initial") && m.customMessage) {
      jobs.push({ kind: "initial", source: m.customMessage, image: false });
      if (cfg.appId) jobs.push({ kind: "initial_image", source: m.customMessage, image: true });
      else warnings.push("Photo version not submitted: add the WHATSAPP_APP_ID secret.");
    }
    if (want.has("followup") && m.customFollowUp) jobs.push({ kind: "followup", source: m.customFollowUp, image: false });
    let headerHandle;
    for (const job of jobs) {
      const built = buildTemplateBody(job.source, vars);
      const name = templateName(businessId, job.kind);
      const row = { business_id: businessId, kind: job.kind, name, language: cfg.lang, body: built.body, params: built.params };
      try {
        if (!built.params.includes("review_link")) throw new Error("The message must include the Review Link");
        if (job.image && !headerHandle) headerHandle = await uploadSampleImage(cfg, await renderReviewImage(m.imageDataUrl ?? null, "Priya"));
        const created = await createTemplate(cfg, name, built.body, built.example, job.image ? headerHandle : void 0);
        await admin.from("whatsapp_templates").insert({ ...row, status: created.status, meta_template_id: created.id });
      } catch (e) {
        await admin.from("whatsapp_templates").insert({ ...row, status: "failed", reason: e instanceof Error ? e.message : String(e) });
      }
    }
  } else {
    const { data: pending } = await admin.from("whatsapp_templates").select("id, meta_template_id").eq("business_id", businessId).eq("status", "pending").not("meta_template_id", "is", null);
    for (const t of pending ?? []) {
      try {
        const s = await fetchTemplateStatus(cfg, t.meta_template_id);
        await admin.from("whatsapp_templates").update({ status: s.status, reason: s.reason }).eq("id", t.id);
      } catch (e) {
        warnings.push(e instanceof Error ? e.message : String(e));
      }
    }
  }
  const { data: rows } = await admin.from("whatsapp_templates").select(COLS).eq("business_id", businessId).order("created_at", { ascending: false }).limit(30);
  return json({ ok: true, templates: rows ?? [], warnings });
});
